INSERT INTO `mod_lore_codex_entry` (`ID`, `Kind`, `Zone`, `SortOrder`, `Faction`, `RequiredState`, `Title`, `Body`, `Sources`) VALUES
(800, 0, 8, 0, 0, 0, 'Swamp of Sorrows', 'The Swamp of Sorrows was once the northern reach of the Black Morass, a vast marshland whose southern half became barren waste after the Dark Portal was destroyed, the land now called the Blasted Lands. What remained was named in honor of those who died in the Second War. Long before, the Atal''ai, exiled priests of the Gurubashi trolls, raised a temple here to their blood god Hakkar, until Ysera of the green dragonflight drowned it beneath the Pool of Tears. Green dragons and their kin still guard the ruin. The orcs of Stonard hold the south as a Horde foothold, while Alliance caravans struggle along the road to Nethergarde Keep. In the north, Broken exiles shelter at the Harborage, beset by the Lost Ones, their own kin driven mad by the journey from Draenor. Murlocs crowd the misty eastern shore, jaguars and crocolisks stalk the mire, and beside the southern road the ghost of an orc hero still waits for orders that never came.', 'warcraft.wiki.gg/wiki/Swamp_of_Sorrows (Black Morass, southern part became barren after the Dark Portal was destroyed, named in honor of Second War dead, Atal''ai temple, Ysera drowned it, Stonard); warcraft.wiki.gg/wiki/Temple_of_Atal''Hakkar (exiled Gurubashi priests fled north into the swamp); quest 1389 description (Lost Ones driven mad by the rigors of the journey to Azeroth); quests 1396, 1421, 1425 (Alliance caravans to Nethergarde); npc_text 1392, quest 2621 (Fallen Hero awaiting orders); DB spawns: Marsh murlocs on the coast, Swamp Jaguar and Sawtooth Crocolisk in the mire'),
(801, 1, 8, 1, 0, 0, 'Misty Valley', 'Misty Valley lies in the northwest corner of the swamp, just north of where the road climbs away toward Deadwind Pass. Fog clings to its sodden floor, and the valley belongs to the swamp itself. Swampwalkers and tangled horrors, lumbering plant-like creatures of root and muck, wander between its pools, and a hulking elemental called the Mire Lord dwells in the valley''s cave. Such creatures are no friend to travelers. A courier carrying an essay of Khadgar''s to Nethergarde Keep once took a wrong turn in the swamp and fled from them in terror, and one of the beasts made off with the precious pages.', 'warcraft.wiki.gg/wiki/Misty_Valley (northwest corner, north of the entrance to Deadwind Pass; pre-Cataclysm Tangled Horrors, Swampwalkers, Swampwalker Elders; Mire Lord in the valley''s cave); quest 1364 description (courier, wrong turn, plant-like swamp creatures, essay taken); creature_loot_template: item 6065 Khadgar''s Essays drops from 764, 765, 766, 1081; DB: Mire Lord 1081 (type elemental) at area 116; Swampwalker and Tangled Horror spawns in area 116'),
(802, 1, 8, 2, 0, 0, 'Splinterspear Junction', 'Splinterspear Junction is where the main road into the swamp divides. The northern branch runs past the Harborage toward the Fallow Sanctuary, while the southern branch bends toward Stonard and the long road to the Blasted Lands. An old orcish watchtower stands near the fork, and scouts out of Stonard keep an eye on the crossing, for beyond it lies Horde country. Alliance travelers on the way to Nethergarde learn to watch the roads here. A short way to the south, the stranded Watcher Biggs keeps lonely guard over the remains of his caravan.', 'warcraft.wiki.gg/wiki/Splinterspear_Junction (main road splits; north branch past the Harborage to Fallow Sanctuary, south branch to Stonard and the Blasted Lands; old orcish watch tower; Horde patrols); DB spawns: Stonard Scout 861 (faction 29) around -10390,-2640 in area 1780; quest 9609 (Watcher Biggs is to the south); DB spawn Watcher Biggs 5476 at -10535,-2836'),
(803, 1, 8, 3, 0, 0, 'The Harborage', 'In the north of the swamp, a cluster of leather huts hung with crystals makes up the Harborage, refuge of the Broken who kept their minds after crossing from Draenor. Their leader Magtoor knows how few they are. The Lost Ones of the Fallow Sanctuary, once their own brethren, kill any who wander near, and they have stolen the sacred draenethyst the exiles fear they cannot do without. The village keeps on careful terms with nearby Stonard and trades with its merchants, for Magtoor believes the Horde would crush his people if they failed to honor it.', 'warcraft.wiki.gg/wiki/The_Harborage (pre-Cataclysm: base of Broken who stayed sane, leather huts hung with crystals); quest 1389 description; creature_text 1776 (Magtoor on honoring the Horde), creature_text 17127 (Avuun: why do you traffic with the Horde); npc_text 8812, 9270; quest 9610 reward text (Holaaru); DB spawns: Magtoor 1776, Anchorite Avuun 17127, Holaaru 18221, Broken Exile 11198 in area 657'),
(804, 1, 8, 4, 0, 0, 'Itharius''s Cave', 'In the hills along the swamp''s western edge lies a cave where Itharius, who looks to all the world like an elf, makes his home. He shares it with a brood of green whelps, adolescents and dreamers alike, that snap at anyone who intrudes. These whelps carry a fine dream dust valued well beyond the swamp: a goblin of Booty Bay who trades in secrets will name his price in it before he gives one away. Few who find the cave know why its master is here.', 'warcraft.wiki.gg/wiki/Itharius (cave near the edge of the swamp, looks after green whelps, appears as an elf in Classic); gossip_menu_option 1341 (What''s an elf like you doing inside a cave like this?); npc_text 1997 (brother trapped in a nightmare); quest 1116 description (dream dust from the dragon whelps of the Swamp of Sorrows, Krazek in Booty Bay); DB spawns: Itharius 5353, Adolescent Whelp 740, Dreaming Whelp 741 only in area 1777'),
(805, 1, 8, 5, 0, 0, 'Fallow Sanctuary', 'Fallow Sanctuary is the village of the Lost Ones in the north of the swamp, east of the Harborage and within sight of the Redridge Mountains. Its huts and campfires belong to draenei twisted further than the Broken, maddened by the journey from their homeworld and hostile to every outsider. Hunters, fishermen, cooks, seers and riftseekers keep up a grim semblance of village life under their chieftains, guarding the draenethyst they stole from the Harborage. One of them, Ongeku, holds a shard so prized that the Gelkis centaurs of distant Desolace covet it. Beasts are kept in cages here, a captive human sits in another, and loot from a plundered Alliance caravan lies scattered nearby.', 'warcraft.wiki.gg/wiki/Fallow_Sanctuary (village of the Lost Ones, within view of Redridge, driven mad with homesickness); quest 1389 description; quest 1373 description (Gelkis of Desolace, draenethyst shard held by Ongeku); quest 9440 description (caged animals at the Fallow Sanctuary); quest 1421 description (wagon dragged to the Fallow Sanctuary); DB spawns in area 76: Lost One Hunter, Fisherman, Cook, Seer, Riftseeker, Chieftain, Draenethyst Crystals, Captured Tarantula/Crocolisk; Galen''s Cage 37118 and Caravan Chest 28024 just outside the area line; creature_queststarter: Uthek the Wise 5397 starts 1373'),
(806, 1, 8, 6, 0, 0, 'The Shifting Mire', 'The Shifting Mire is the broad, sodden heart of the swamp, lying west of the Pool of Tears. Swamp jaguars hunt between its twisted trees alongside sorrow spinners and young sawtooth crocolisks, and a thorny elemental known as Molt Thorn wanders its paths. Lost Ones wade the shallows, fishing and scavenging far from their village. North of Stonard, a man named Galen Goodward once kept his camp in the mire, and his strongbox still waits there, locked by a trick that only its owner knows.', 'warcraft.wiki.gg/wiki/The_Shifting_Mire (central section west of the Pool of Tears; jaguars, spinners, young crocolisks, Lost Ones); DB spawns in area 1798: Swamp Jaguar x22, Molt Thorn 14448 (type elemental), Sorrow Spinner, Young Sawtooth Crocolisk, Lost One Mudlurker and Fisherman; quest 1393 description (strongbox in his camp north of Stonard, opened by a trick only Galen knows); gameobject 32569 Galen''s Strongbox in area 1798'),
(807, 1, 8, 7, 0, 0, 'Stonard', 'Stonard is one of the oldest orc settlements in Azeroth, first raised by the old Horde as an outpost in the Black Morass after the Dark Portal opened. Probably lost in the wars that followed, it has been re-established by the new Horde, and it still keeps a great hall guarded by two burrows. Here Fel''zerul studies the sunken temple at the Warchief''s command, Helgrum the Swift struggles to keep word flowing to distant Kargath, and Dispatch Commander Ruag relays the orders of Orgrimmar. Wayfinders and cartographers set out to chart the unmapped swamp, and a captured human spy waits in custody.', 'warcraft.wiki.gg/wiki/Stonard (founded by the Old Horde in the Black Morass after the first opening of the Dark Portal, re-established by the new Horde, great hall and two burrows, wayfinders and cartographers mapping the swamp); quest 1424 description; quest 1418 description; quest 2622 description; quest 1372 description (human infiltrator taken to Stonard); quest 9440 description; DB spawns: Stonard Wayfinder 865, Stonard Cartographer 867, Infiltrator Marksen 5416 in area 75; quest 1418 reward text (Neeka''s outrunner to Stonard)'),
(808, 1, 8, 8, 0, 0, 'Pool of Tears', 'The Pool of Tears is the great lake on the eastern side of the swamp, and beneath its dark water lies the Temple of Atal''Hakkar. The Atal''ai trolls built it to call their blood god Hakkar into the world, and the green dragonflight sank it to stop them. Ruins of the Atal''ai still lie scattered along the shore and under the water, where relics and tablets can be found, and cursed and mummified trolls haunt the stones. Ravenous sawfin frenzies swarm the water. Green dragonkin stand guard over the place, among them the ancient drake Somnus and the dragon Jade, who would sooner destroy an intruder than let one enter the temple.', 'warcraft.wiki.gg/wiki/Pool_of_Tears (pre-Cataclysm lake, temple sunk under its waters, Atal''ai ruins at the shore and underwater, frenzies); warcraft.wiki.gg/wiki/Temple_of_Atal''Hakkar; quest 9610 description (Somnus, dragonkin, carnivorous fish); creature_text 1063 (Jade); DB spawns in area 74: Atal''ai Artifact and Atal''ai Tablet objects, Cursed/Mummified/Enthralled Atal''ai, Sawfin Frenzy 14356, Somnus 12900, Jade 1063'),
(809, 1, 8, 9, 0, 0, 'Sorrowmurk', 'East of the Pool of Tears and the sunken temple lies Sorrowmurk, a stretch of swamp held by the green dragonflight. Scalebane captains, wyrmkin dreamwalkers and elder dragonkin patrol its pools in such numbers that few but the boldest travelers try to cross it, and among them walks a rare dragonspawn called Lord Captain Wyrmak. The dragons are not alone. Atal''ai priests and the cursed and mummified remnants of their tribe still creep through the murk, close to the drowned temple of their god.', 'warcraft.wiki.gg/wiki/Sorrowmurk (just east of the Pool of Tears and the Sunken Temple, crawling with green dragonspawn, inhospitable for all but the most adventurous); warcraft.wiki.gg/wiki/Lord_Captain_Wyrmak (rare green dragonspawn in Sorrowmurk); DB spawns in area 1778: Scalebane Captain 745, Elder Dragonkin 746, Wyrmkin Dreamwalker 743, Lord Captain Wyrmak 14445, Atal''ai Priest, Cursed and Mummified Atal''ai'),
(810, 1, 8, 10, 0, 0, 'Stagalbog', 'Stagalbog is the dense marsh south of the Pool of Tears, pressed up against the mountains along the swamp''s southern border. Deathstrike tarantulas lurk among the trees, and murlocs of the marsh tribes, inkspewers, flesheaters and oracles, range inland from the coast. A cave at the edge of the mountains shelters a murloc called the Swamp Talker, who can summon the spirits of the swamp to fight beside it, and whose kin waylay travelers on the swamp''s roads.', 'warcraft.wiki.gg/wiki/Stagalbog (south of the Pool of Tears, borders the southern mountain range, Stagalbog Cave at the edge of the mountains); warcraft.wiki.gg/wiki/Swamp_Talker (located in Stagalbog Cave, Summon Swamp Spirit); quest 2622 and 2623 descriptions (ambush, Swamp Talker took the orders); creature_loot: item 8463 Warchief''s Orders from Swamp Talker 950; DB spawns in area 1797: Deathstrike Tarantula, Marsh Inkspewer, Flesheater, Oracle; Swamp Talker 950 at -10967,-3658'),
(811, 1, 8, 11, 0, 0, 'Misty Reed Strand', 'Misty Reed Strand is the long, fog-bound coast along the swamp''s eastern edge, where the marsh gives way to the Forbidding Sea. Marsh murlocs crowd the shore in great numbers, and monstrous crawlers and sawtooth snappers scuttle through the surf. Sun-dried driftwood washes up among the reeds, prized by anyone in the swamp who needs timber sounder than the spongy wood of its trees. Stonard keeps a close eye on this coast. The orc Katar patrols the beach, nursing a bitter hatred of the sea and of every fish man it spawns, and crawler legs gathered here are shipped all the way to Orgrimmar.', 'warcraft.wiki.gg/wiki/Misty_Reed_Strand (gloomy coastline, driftwood, crocolisks, crabs, murlocs; Alliance collect driftwood, Horde hunt murlocs); quest 1398 description (strong, dry wood, not the spongy wood of the swamp''s trees); quest 1426 description (Katar); quest 1430 description (crawler legs shipped to Orgrimmar); DB spawns in area 300: Marsh Inkspewer x38, Silt Crawler, Monstrous Crawler, Sawtooth Snapper, Sundried Driftwood objects, Katar 5593'),
(812, 1, 8, 12, 0, 0, 'Misty Reed Post', 'Just inland from the southern end of Misty Reed Strand, a small Horde camp keeps watch over the sea. Tok''Kar and his soldiers are stationed here to hold back the murlocs, or to warn Stonard if a force comes too large to stop. Between shifts of guard duty Tok''Kar cooks for his troops and forges weapons from the claws of sawtooth snappers, for the more blades the camp has ready, the better its chances. It is a spare life of fire, mead and steel, and Tok''Kar admits he would not mind if Stonard one day sent them a proper burrow, or at least a tower.', 'quest 698 description (outpost near the beach, guard duty and cooking); quest 699 description, reward and request texts (protect or warn Stonard, weapons from claws, burrow or tower); DB spawns in area 1978: Tok''Kar 5592, Stonard Hunter 863 x5, Stonard Shaman 868'),
(813, 2, 8, 1, 0, 0, 'Itharius', 'Itharius dwells in a cave on the western edge of the swamp, an elf to all appearances, sharing it with a brood of green whelps. He greets strangers as if he has been expecting them. Fate and forces beyond it, he says, have brought them to him for a reason, and it is one he takes no pleasure in being part of. Many decisions lie ahead of them, and he hopes they are wise enough to make the correct ones, for he insists that there are correct choices. Idle curiosity about why he lives in a cave earns only a cool dismissal.', 'npc_text 1995 (default greeting), 1996 (reply to ''What''s an elf like you doing inside a cave like this?''); DB spawns: Itharius 5353 with Adolescent and Dreaming Whelps in area 1777; warcraft.wiki.gg/wiki/Itharius (green dragon, appears as a high elf in Classic, Ysera''s flight); npc_text 1995, 1997, 1998, 1999; creature 5353 faction 35 (friendly to all)'),
(814, 2, 8, 2, 0, 0, 'Magtoor', 'Magtoor leads the Broken exiles of the Harborage, among the few draenei who came through the Dark Portal and kept their reason. He has watched his former brethren at the Fallow Sanctuary become monsters that prey on his people, and he fears that without their sacred draenethyst the exiles too may lose their way. Magtoor is a realist about his neighbors. He trades with merchants in Stonard and believes the Horde would crush his village if it failed to honor them.', 'warcraft.wiki.gg/wiki/Magtoor (pre-Cataclysm: Broken leader of a small group who kept their noble roots, came through the Dark Portal); quest 1389 description; creature_text 1776 groups 0-3; creature 1776 faction 35'),
(815, 2, 8, 3, 1, 8, 'Anchorite Avuun', 'Anchorite Avuun is a draenei who has come to the Harborage to study the Lost Ones of the Fallow Sanctuary. He has faith that the fel energies consuming them can be cured, and that the same cure would undo the damage done to the Broken. He has little patience for the village''s dealings with the Horde, whose foul ways he thinks beneath his hosts. His gravest fear lies in Stonard. He is certain the blood elf Cersei Dusksinger is cursing the Lost Ones with still darker fel magic, and for those already twisted past saving, he asks only that they be granted mercy.', 'npc_text 8812; creature_text 17127 groups 0, 1, 3; quest 9448 description and reward text; warcraft.wiki.gg/wiki/The_Harborage (Avuun arrived to study the Broken and look for a cure, urged residents to stop trading with the Horde)'),
(816, 2, 8, 4, 2, 8, 'Cersei Dusksinger', 'Cersei Dusksinger is a blood elf warlock working out of Stonard, and she has little good to say about the swamp, its air or the food in Stonard. She is perfecting a weapon against the draenei, testing fel-tainted morsels on the captive livestock of the Lost Ones so that the curse passes into whoever eats them. She scorns the orcs for sitting idle while others plunder the power that lies so close at hand. Anchorite Avuun''s opposition she takes as a personal challenge, vowing that when she is finished, the draenei will wish they were Lost Ones.', 'quest 9440 description and reward text; creature_text 17109 (orcs are fools, Avuun dares to oppose me, cured ham steak from Thultash, no fresh air in this swamp); warcraft.wiki.gg/wiki/Cersei_Dusksinger (blood elf warlock in Stonard); creature 17109 faction 1604 (Silvermoon, enemy of Alliance)'),
(817, 2, 8, 5, 0, 0, 'Fallen Hero of the Horde', 'Beside the southern road toward the Blasted Lands stands the ghost of the orc who commanded Thrall''s Grasp, twenty of the Warchief''s most accomplished and honored soldiers. He had the regiment make camp here on the border to await orders from Orgrimmar, but weeks passed without word and the men grew restless. Young, ambitious and afraid of nothing, he led them into the Blasted Lands, a decision he has regretted ever since: one bad choice, he says, and many horrible outcomes, all of them his fault. Now his spirit lingers where he made that choice, warning travelers of the death and chaos beyond and seeking anyone willing to help him regain his honor.', 'npc_text 1391 (greeting before any quest), 1392 and 1411 (shown while on quest 2784), 1451-1454 (shown while on quest 2801); conditions: gossip menu 840 option 0 needs quest 2784 taken; option 1 and npc_text 1451 need quest 2801 taken; quest 2784 reward text; quest 2621 description; warcraft.wiki.gg/wiki/Fallen_Hero_of_the_Horde (Trebor, ghost beside the road south toward the Blasted Lands); creature 7572 faction 35; creature_text 7668-7671 (Give my regards to Commander Trebor)'),
(818, 2, 8, 6, 2, 0, 'Fel''zerul', 'Fel''zerul came to Stonard on the Warchief''s orders to look into strange happenings at the Temple of Atal''Hakkar, only to find the temple already sunk beneath the Pool of Tears and green dragons claiming to guard it as protectors of Azeroth. He has set out to piece the mystery together from Atal''ai relics. The Atal''ai, he knows, are a tribe of dark casters who practiced forbidden magic, and he hopes their spells might prove useful to the Horde.', 'quest 1424 description and request text; quest 1429 description; quest 1444 description; quest 1445 description; creature_text 1443 (I hereby destroy these instruments of evil! For the Horde!); creature 1443 faction 29'),
(819, 2, 8, 7, 1, 0, 'Watcher Biggs', 'Watcher Biggs was escorting a caravan from Darkshire bound for Nethergarde Keep when Lost Ones fell upon it, killing the guards and scattering the supplies. He alone survived. Since then he has camped beside his broken wagon south of the Harborage, a lonely figure on the swamp road, sworn to protect what remains of the shipment from the jaguars, spiders and young crocolisks that skulk ever closer to his camp.', 'quest 9609 description (caravan from Darkshire, sole survivor, south of the Harborage); quest 1396 description; quest 1421 description and reward text; quest 1398 description; creature 5476 faction 12 (Stormwind, enemy of Horde)'),
(820, 2, 8, 8, 0, 0, 'Galen Goodward', 'Galen Goodward is a human who made his camp in the swamp north of Stonard, and who now sits in a cage at the edge of the Fallow Sanctuary, certain his captors mean to eat him. He promises great treasure to anyone who will lead him to safety: a strongbox in his camp, locked so that only a trick of his own can open it, and he swears he will teach that trick to whoever helps him escape.', 'quest 1393 description and reward text; creature_text 5391 groups 3-5; quest 9440 request text (that stupid human they have out there in the cage); gameobject 37118 Galen''s Cage at -9898,-3724; 32569 Galen''s Strongbox in area 1798; creature 5391 faction 35'),
(821, 2, 8, 9, 0, 0, 'Noboru the Cudgel', 'Noboru the Cudgel is a Lost One who roams the swamp with his gang, killing any draenei who cross his path. For months he has been a terror to the Harborage, a direct threat to its survival, and the Broken admit they never had the strength to face him. His great club has become a symbol of all the brutality they have suffered at the hands of their maddened kin.', 'quest 1392 description and reward text; creature 5477 faction 51 (hostile to all), spawn at -10174,-3505'),
(822, 2, 8, 10, 0, 0, 'Somnus', 'Somnus is an ancient drake of the green dragonflight who dwells at the Pool of Tears with his dragonkin, above the drowned Temple of Atal''Hakkar. Anyone who goes digging for Atal''ai relics along the shore is warned of him first. His renown reaches even the black dragonflight. The black drake Emberstrife names him the drake champion of the Green Flight and sends Horde warriors into the swamp to bring back his skull, as proof that the children of the Aspects can be humbled as surely as the Aspects themselves.', 'quest 9610 description (guarded by Somnus, an ancient green dragon, and his dragonkin); quest 6583 description (Emberstrife: Somnus, drake champion of the Green Flight; bring his skull); DB spawn: Somnus 12900 at -10661,-3924 (area 74); warcraft.wiki.gg/wiki/Somnus'),
(823, 3, 8, 1, 0, 0, 'The Sunken Temple', 'Horde and Alliance alike have come looking for the Temple of Atal''Hakkar, the shrine of the Atal''ai trolls to their blood god Hakkar. In Stormwind, the aged dwarf Brohann Caskbelly asks for help with his final task for the Explorers'' League, a temple he once hunted by gryphon and never found. In Stonard, Fel''zerul has come at the Warchief''s command to learn what happened there, and gathers Atal''ai artifacts in the hope that the trolls'' forbidden magic might serve the Horde. Searchers soon learn that the temple lies sunk beneath the Pool of Tears, ringed by green dragons who claim to protect Azeroth.', 'quests 1448, 1469, 1475 (Brohann Caskbelly, Rhapsody Shindigger); quest 9610; quests 1424, 1429, 1444, 1445, 1446'),
(824, 3, 8, 2, 0, 0, 'The Lost Ones', 'The Broken of the Harborage and the Lost Ones of the Fallow Sanctuary were once one people. The Lost Ones look as the Broken look, but the rigors of the journey to Azeroth drove them mad, and now they catch or kill any who wander near their village. They have stolen the draenethyst crystals sacred to the exiles, and Magtoor, lacking the strength to take them back, fears that without them his people too may lose their way. Worst of all is Noboru the Cudgel, whose gang has plagued the Harborage for months, killing any draenei who cross its path.', 'quests 1389, 1392, 9440, 9448 (descriptions and reward texts); creature_text 17109, 17127'),
(825, 3, 8, 3, 0, 0, 'Thrall''s Grasp', 'The ghost on the road to the Blasted Lands tells his tale to anyone who will listen. He commanded Thrall''s Grasp, twenty of the Warchief''s finest soldiers, and while they camped on the border awaiting orders from Orgrimmar he grew impatient and led them into the Blasted Lands, a choice that brought horrors he blames on no one but himself. To the Horde he confesses that he must know what became of those orders, and sends them to Dispatch Commander Ruag in Stonard. At Nethergarde, Ambassador Ardalan urges the Alliance to stop squabbling with orcs over scorched earth while the true power in these lands grows, and to hear the fallen hero, who knows the truth behind the Blasted Lands.', 'npc_text 1392, 1451-1456; quests 2784, 2621, 2622, 2623, 2783, 2801, 2681 (descriptions and reward texts); warcraft.wiki.gg/wiki/Fallen_Hero_of_the_Horde'),
(826, 3, 8, 4, 1, 0, 'The Lost Caravan', 'Supplies for Nethergarde Keep travel from Darkshire by the long swamp road, and not all of them arrive. When Lost Ones ambushed one such caravan, killing its guards and scattering its supplies, only Watcher Biggs survived. He has made camp beside his broken wagon on the road south of the Harborage and sworn to protect what remains, but the swamp''s jaguars, spiders and young crocolisks are closing in, and his first request of anyone who stops to help is to drive them back.', 'quests 9609, 1396, 1421, 1398, 1425 (descriptions and reward texts)'),
(827, 3, 8, 5, 2, 0, 'Threat from the Sea', 'Stonard''s eastern flank faces the sea, and the Horde takes the danger seriously. Dar, a trader in Stonard, gathers sawtooth meat for the soldiers at Misty Reed Post and monstrous crawler legs for his customers in Orgrimmar. At the post, Tok''Kar welcomes the fresh meat, turns sawtooth snapper claws into weapons for the camp''s defense, and sends willing hands on to Katar, who walks the beach on patrol. Katar''s hatred of the sea and the murlocs it spawns runs deep. He calls himself as patient and enduring as an old stone of Draenor, and would cleanse every world of the fish men if he had the army to do it. Each murloc slain along the strand brings him a grim pleasure, and Tok''Kar rewards those who bring a smile to Katar''s face with one of his finished blades.', 'quests 698, 699, 1422, 1426, 1427, 1428, 1430 (descriptions, request and reward texts)'),
(828, 3, 8, 6, 0, 0, 'The Dreamer''s Charge', 'Within the sunken temple lies a gem into which Eranikus of the green dragonflight, keeper of the temple, has poured part of his essence. His charge, to ensure that the trolls never again bring forth their god, has for now ended in failure, and he feels his grip on the Dream twisting into chaos. Through the gem he begs whoever finds it to place it in the essence font of his lair, so that the magic of his flight may purge the taint from his mind and let him rest.', 'quest 3373 description and reward text; quest 3374 description and reward text; quest 3512 description; creature_text 5353 (I have given you an oathstone); item 10589 Oathstone of Ysera''s Dragonflight starts 3374; item 10454 Essence of Eranikus starts 3373; quest_template_addon 3374 PrevQuestID 3373');
INSERT INTO `mod_lore_codex_part` (`Entry`, `Part`, `MinState`, `MaxState`, `Body`, `Sources`) VALUES
(803, 1, 8, 255, 'Since the draenei joined the Alliance, the Harborage has drawn new attention. The draenei Anchorite Avuun has come to study the Lost Ones in hope of a cure, and it troubles him that the village deals with the Horde at all. The Broken scholar Holaaru, meanwhile, studies Atal''ai relics from the Pool of Tears, hoping to understand the history of his new world.', 'creature_text 17127 groups 0, 1, 3; npc_text 8812, 9270; quest 9610 description and reward text; warcraft.wiki.gg/wiki/Anchorite_Avuun, warcraft.wiki.gg/wiki/Holaaru (both added in patch 2.0.1)'),
(804, 1, 0, 255, 'Itharius is no elf. He speaks for Ysera''s green dragonflight, and he waits in this cave for those who have walked the Sunken Temple and carry part of the essence of his brother Eranikus, whose torment he means to end.', 'npc_text 1997, 1999 (gossip shown only with the Chained Essence after quest 3373); quest 3374 description'),
(807, 1, 8, 255, 'Since the blood elves joined the Horde, Stonard has a guest from Quel''Thalas. The warlock Cersei Dusksinger has little good to say about the swamp, its air or its food, and she scorns the orcs for sitting idle so close to so much power. Meanwhile she is perfecting a curse meant for the draenei.', 'creature_text 17109; quest 9440 description; warcraft.wiki.gg/wiki/Cersei_Dusksinger'),
(810, 1, 0, 255, 'The Swamp Talker has more to answer for than most. When murlocs ambushed a party of Stonard soldiers bound for the Blasted Lands, it was the Swamp Talker who tore the Warchief''s orders from a messenger''s hands as a spear struck him down, and carried them off to its cave.', 'quest 2622 and 2623 descriptions; creature_loot: item 8463 Warchief''s Orders from Swamp Talker 950'),
(813, 1, 0, 255, 'To those who carry part of the essence of Eranikus, Itharius abandons his pretenses. He is of Ysera''s green dragonflight, and Eranikus is his brother. The dragons destroyed the physical form of the god the Atal''ai called forth and sank its temple, but its corruption ran deeper than they believed. Eranikus, charged with watching over the sunken temple, fell to it unwittingly and now lies trapped in a nightmare within the Dream. His agony roused Itharius from his own dreaming, and ending that torment is now his charge.', 'npc_text 1997, 1998, 1999; conditions: gossip menu 1341 option 1 needs item 10455 and quest 3373 rewarded; quest 3374 description'),
(814, 1, 8, 255, 'Since the draenei joined the Alliance, one of them has come to stay. Magtoor welcomes Anchorite Avuun to the Harborage for as long as he likes, yet asks him plainly what he truly believes he can accomplish. He also passes on a warning from Stonard, where one of his trading partners has heard a blood elf raving about a horrible disease she means to use against the draenei.', 'creature_text 1776 groups 0, 2, 3'),
(817, 1, 0, 255, 'The orders had been sent after all. Dispatch Commander Ruag relayed them, but murlocs ambushed the messengers on the road and the Swamp Talker carried the orders off. When they were brought to him at last, the hero found his fear confirmed: had he waited, nineteen of his men could have been spared the agony they suffered.', 'quests 2622, 2623 descriptions; quest 2623 reward text'),
(817, 2, 0, 255, 'In time he told the rest. He had fled the forces that overwhelmed his men, then returned to rescue them, only to be captured, tortured in turn with his lieutenant Kirith and beaten until dead. In a lull between torments Kirith told him the regiment''s fate. The demon lord Razelikh had torn out their souls, binding nine to stones near the Dark Portal and dividing the rest among Archmage Allistarj, Lady Sevine and Grol the Destroyer. Soulless, their bodies cannot be killed, and they serve those who bind them.', 'npc_text 1451, 1452, 1453, 1454 (gossip shown while on quest 2801)'),
(817, 3, 0, 255, 'At last the stones were shattered and his men were freed. As each soul broke loose it spoke a few last words: of freedom, of the agony ending, of a warning for Thrall, and of their commander, Trebor, whose fault, they insisted, it had not been. The tortured souls could finally rest, but the hero''s work was not yet over.', 'creature_text 7668-7671 group 1; quest 2681 reward text'),
(818, 1, 0, 255, 'A sentence of exile written in blood on dried flesh led him to a disgraced Atal''ai priest in the Hinterlands, and through him to the prophecy of Jammal''an the Prophet, who believes Hakkar''s return will grant his tribe immortality. Fel''zerul calls it foolish trickery to bring about a premature doomsday, but the exile''s talk of enchanted fetishes concerns him greatly, and he means to seize them.', 'quest 1429 description; quest 1444 description; quest 1445 description'),
(818, 2, 0, 255, 'When the fetishes of Hakkar were finally laid before him, Fel''zerul did not keep them for study. He destroyed them on the spot as instruments of evil, in the name of the Horde.', 'quest 1445 reward text; creature_text 1443'),
(819, 1, 0, 255, 'Stunned in the attack, Biggs had glimpsed one of the wagons being dragged north to the Fallow Sanctuary. It carried a chest of reagents the wizards of Nethergarde need for their studies, work tied to the Dark Portal that he calls vital to the security of the Alliance.', 'quest 1421 description and reward text'),
(819, 2, 0, 255, 'To mend his own wagon Biggs needed strong, dry wood, not the spongy timber of the swamp''s trees. While he worked he sent the most vital supplies ahead to Nethergarde, where Quartermaster Lungertz had already given Biggs and his caravan up for lost.', 'quest 1398 description; quest 1425 description and reward text'),
(820, 1, 8, 255, 'Word of the caged human has reached Stonard. The blood elf warlock Cersei Dusksinger knows of him, and when her helpers come back from feeding her morsels to the Lost Ones'' captive beasts, she asks in alarm whether they wasted any on that stupid human in the cage.', 'quest 9440 request text'),
(820, 2, 0, 255, 'Led out of danger, Galen thanked his rescuer, swore he would remember them always and pointed the way to his camp north of Stonard. Then he whispered his secret and slipped away into the swamp. The strongbox''s keyhole is filled with black resin and cannot be picked, but a hidden latch on its underside opens it.', 'creature_text 5391 groups 3-5; quest 1393 reward text (at gameobject 32569, the quest ender)'),
(821, 1, 0, 255, 'When Noboru''s cudgel was laid before Magtoor, the leader of the Harborage could hardly believe it. If Noboru was truly dead, it was a joyous day for the exiles, and the one who brought down their tormentor is counted a true friend of the Harborage.', 'quest 1392 reward text'),
(823, 1, 8, 255, 'Since the draenei came to Azeroth, the Broken of the Harborage have taken an interest as well. The scholar Holaaru seeks Atal''ai relics from the shores and depths of the Pool of Tears, braving Somnus and his dragonkin, for how else, he asks, are the Broken and the draenei to fit in if they do not understand the history of their new world?', 'quest 9610 description and reward text'),
(823, 2, 0, 255, 'Brohann''s lost pilot had known all along. The gryphon rider Rhapsody Shindigger, deep in his cups, fell from his mount into the pool, was sucked down among the trolls and swam out as fast as he could, carrying off a troll relic as a souvenir. It proved to Brohann that his temple lay below indeed.', 'quest 1469 description and reward text; quest 1475 description'),
(823, 3, 0, 255, 'For the Horde, a sentence written in blood led to an Atal''ai priest exiled to the Hinterlands. He told of Jammal''an the Prophet, who believes Hakkar''s return will make his tribe immortal, and warned that the artifacts were harmless, but that if Jammal''an has found the right enchantment for the fetishes of the summoning, the world lies in great peril.', 'quest 1429 description; quest 1444 description; quest 1445 description'),
(824, 1, 0, 255, 'Noboru''s reign of terror ended at last. When his cudgel, the very symbol of the brutality the exiles had suffered, was brought to Magtoor, the Harborage counted it a joyous day and welcomed his slayer as a friend.', 'quest 1392 description and reward text'),
(824, 2, 8, 255, 'Since the draenei joined the Alliance, Anchorite Avuun has come to the Harborage to study the Lost Ones in hope of a cure. He is sure that the blood elf Cersei Dusksinger of Stonard has been cursing them, for several are now corrupted further, cursed with still more fel energy. Those, he believes, are beyond help, and he asks only that they be given a merciful end.', 'quest 9448 description and reward text; creature_text 17127'),
(824, 3, 8, 255, 'Since the blood elves joined the Horde, the warlock Cersei Dusksinger has been working out of Stonard on a weapon against the draenei, and the Lost Ones, their backward cousins, are her test subjects. Her helpers feed fel-tainted morsels to the Lost Ones'' caged livestock, so that the curse passes to those who slaughter and eat them. That, she crows, will show the stuffy anchorite at the Harborage.', 'quest 9440 description; creature_text 17109'),
(825, 1, 0, 255, 'Ruag swore he had relayed the orders. The soldiers who carried them were ambushed by murlocs on the way to the Blasted Lands and brutally beaten, and only one survived, if it could be called surviving: Bengor, who can hardly speak or walk. Whatever became of the orders, Ruag warned, prying too far might cost the curious their nose.', 'quest 2621 reward text; quest 2622 description'),
(825, 2, 0, 255, 'Bengor managed a few words before he passed out: a murloc called the Swamp Talker had torn the orders from his hands as a spear struck him, and fled east to a cave. The orders were recovered at last, and they were worse than the hero had imagined. Had he waited, nineteen of his men could have been spared the agony they faced.', 'quest 2623 description and reward text; item 8463 Warchief''s Orders (The seal is broken.)'),
(825, 3, 0, 255, 'The rest of his story is darker. Forces too great for the regiment overwhelmed it. He fled the slaughter, came back to rescue his men and was captured, tortured beside his lieutenant Kirith and beaten until dead. Kirith told him what had become of the regiment. The demon lord Razelikh had torn out their souls, keeping nine bound to stones near the Dark Portal and giving three apiece to Allistarj, Sevine and Grol. Eighteen stones of binding must be shattered to free them.', 'npc_text 1451-1456 (gossip shown while on quest 2801); quest 2681 description'),
(825, 4, 0, 255, 'The stones were shattered and the men of Thrall''s Grasp set free. As each soul broke loose it spoke a few last words: of freedom, of agony ending, of a warning that must reach Thrall, and of its commander, Trebor, whose fault, they said, it had not been. The tortured souls could rest at last, though the hero''s work was not yet over.', 'creature_text 7668-7671 group 1; quest 2681 reward text'),
(825, 5, 0, 255, 'The hero summoned another to give thanks. The ghost of a tauren, Corporal Thund Splithoof, appeared beside him and declared that the champions had honored them all, and that thanks alone were not enough. He offered a relic of old, for which the dead no longer had any use, to serve them in the fight against the Legion.', 'quest 2702 description and reward text; quest 2701 description; creature_text 7572 (Per your request, Corporal Splithoof has come); warcraft.wiki.gg/wiki/Corporal_Thund_Splithoof (tauren ghost)'),
(826, 1, 8, 255, 'Since the draenei joined the Alliance, help for Biggs can come from an unexpected quarter. Magtoor has told Anchorite Avuun of the stranded watcher south of the Harborage, and the anchorite sends travelers down the road to lend the caravan''s sole survivor their aid.', 'quest 9609 description (Magtoor informed Avuun; sole survivor; somewhere to the south); warcraft.wiki.gg/wiki/Anchorite_Avuun (added in patch 2.0.1)'),
(826, 2, 0, 255, 'Then Biggs remembered more. Before his sight went black he had seen one of the wagons dragged north to the Fallow Sanctuary, and in it a chest of reagents for the wizards of Nethergarde, whose work at the Dark Portal is vital to the security of the Alliance. With the reagents taken back from the Lost Ones'' village, the wizards can continue their work.', 'quest 1421 description and reward text'),
(826, 3, 0, 255, 'To mend his wagon Biggs needed sun-dried driftwood from the eastern coast, since the swamp''s own timber is too spongy to serve. While he made his repairs he entrusted the most vital supplies to his rescuer for the final road to Nethergarde, where Quartermaster Lungertz had already given Biggs and his caravan up for lost.', 'quest 1398 description; quest 1425 description and reward text'),
(828, 1, 0, 255, 'The font failed him. Even its sanctity had been tainted by the accursed god, and as the gem was laid inside, Eranikus felt his essence torn from him and an eternal nightmare taking hold. Chained in darkness, he implored his rescuer to find one of the green dragonflight to stop it.', 'quest 3373 reward text'),
(828, 2, 0, 255, 'His plea led to Itharius in his cave in the swamp, who gave an oathstone of Ysera''s Dragonflight. Engaging it, the bearer swore to aid the flight in redeeming a soul worthy of redemption, and the first of many sacrifices asked of them was the chained gem itself, so that Itharius might begin the slow work of reaching his brother.', 'quest 3374 description and reward text; creature_text 5353; item 10589 Oathstone of Ysera''s Dragonflight starts 3374'),
(828, 3, 0, 255, 'The first step led far north to eastern Winterspring, to Umbranse the Spiritspeaker, a human medium who speaks for the dead. Eranikus is not truly dead, Itharius explained, but lies between sleep and death, twisted within a weave of nightmares, and through the medium they might still reach him.', 'quest 3512 description');
